package com.example.kyrgyzkeyboard.utils

import com.example.kyrgyzkeyboard.keyboard.KyrgyzAlphabet

/**
 * 柯尔克孜语字符工具（纯函数，无副作用）。
 *
 * 字符集与 QWERTY 映射与 [com.example.kyrgyzkeyboard.keyboard.KyrgyzKeyboardLayouts] 保持一致，
 * 用于文本判定、规范化、以及硬件键盘 -> 柯尔克孜字母的输入映射。
 */
object KyrgyzCharacterUtils {

    /** 34 个字母全集（来自 [KyrgyzAlphabet.LETTERS]，避免重复维护）。 */
    val ALL_LETTERS: Set<String> = KyrgyzAlphabet.LETTERS.toSet()

    /** 元音字母集合（framework.md 中列出的 8 个）。 */
    val VOWELS: Set<String> = setOf(
        "\u0627", // ا
        "\u06D5", // ە
        "\u06C6", // ۆ
        "\u06CC", // ى
        "\u064A", // ي
        "\u06C5", // ؤ
        "\u0626", // ئ
        "\u0621"  // ء
    )

    /** 辅音字母集合 = 全集 - 元音。 */
    val CONSONANTS: Set<String> = ALL_LETTERS - VOWELS

    /** 附加符号（fatha / kasra / damma / shadda）。 */
    val DIACRITICS: Set<String> = KyrgyzAlphabet.DIACRITICS.toSet()

    /**
     * QWERTY 键位 -> 柯尔克孜字母 的映射。
     * 与 [com.example.kyrgyzkeyboard.keyboard.KyrgyzKeyboardLayouts.DefaultLayout] 主键位一致，
     * 变体（长按）不在此映射中，由 UI 层单独处理。
     */
    private val QWERTY_TO_KYRGYZ: Map<Char, String> = mapOf(
        // 第 1 排
        'q' to "\u0642", 'w' to "\u0648", 'e' to "\u06D5", 'r' to "\u0631",
        't' to "\u062A", 'y' to "\u06CC", 'u' to "\u0626", 'i' to "\u0649",
        'o' to "\u067E", 'p' to "\u0621",
        // 第 2 排
        'a' to "\u0627", 's' to "\u0633", 'd' to "\u062F", 'f' to "\u0641",
        'g' to "\u06AF", 'h' to "\u06C1", 'j' to "\u062C", 'k' to "\u06A9",
        'l' to "\u0644",
        // 第 3 排
        'z' to "\u0632", 'x' to "\u062E", 'c' to "\u0686", 'v' to "\u0698",
        'b' to "\u0628", 'n' to "\u0646", 'm' to "\u0634"
    )

    /** 单字符是否属于柯尔克孜字母表。 */
    fun isKyrgyzLetter(char: Char): Boolean =
        ALL_LETTERS.contains(char.toString())

    /** 单字符是否为元音。 */
    fun isVowel(char: Char): Boolean =
        VOWELS.contains(char.toString())

    /**
     * 阿拉伯写法文本规范化：
     * 1. 去除阿拉伯 tatweel（U+0640）拉长符
     * 2. 折叠连续空白
     * 3. 统一 Java/波斯 ي 变体到 U+06CC
     */
    fun normalizeArabicText(text: String): String {
        if (text.isEmpty()) return text
        val sb = StringBuilder(text.length)
        var lastWasSpace = false
        for (raw in text) {
            val ch = when (raw) {
                '\u0640' -> continue          // 忽略 tatweel
                '\u064A' -> '\u06CC'          // Arabic Yeh -> Farsi Yeh (统一形)
                else -> raw
            }
            if (ch.isWhitespace()) {
                if (!lastWasSpace) sb.append(' ')
                lastWasSpace = true
            } else {
                sb.append(ch)
                lastWasSpace = false
            }
        }
        return sb.toString().trim()
    }

    /**
     * 硬件键盘按键 -> 柯尔克孜字母。返回 null 表示无映射（如数字/符号/未定义键）。
     */
    fun getKeyboardMapping(qwertyChar: Char): String? =
        QWERTY_TO_KYRGYZ[qwertyChar.lowercaseChar()]
}